#include <charconv>
#include <cstdint>
#include <filesystem>
#include <iostream>
#include <string>
#include <string_view>
#include <system_error>
#include <vector>

#include "filehash.h"
#include "merkle.h"

namespace {

// hash/root 共用的文件参数解析规则：
//  * 第一个单独的 "--" 是选项结束标记，它本身不算文件；
//  * 结束标记之前，凡是以连字符开头的参数都按选项解释；这两个命令不支持
//    任何选项，因此一律构成用法错误（即使同名文件可以读取）；
//  * 结束标记之后的所有参数一律是文件路径（包括 "-notes.bin"、"--version"、
//    单独的 "-" 以及再次出现的 "--"），按字面定位真实文件。
struct FileArgs {
    std::vector<std::filesystem::path> files;
    std::string unsupported;  // 遇到的不支持选项原文；非空即用法错误
};

FileArgs parse_file_args(char* const* argv, int first, int last) {
    FileArgs args;
    bool options_ended = false;
    for (int i = first; i < last; ++i) {
        const std::string_view arg{argv[i]};
        if (!options_ended && arg == "--") {
            options_ended = true;
            continue;  // 结束标记本身不占文件位置
        }
        if (!options_ended && !arg.empty() && arg.front() == '-') {
            // 立即返回：批次中即使还有正常文件，也不能继续产出结果。
            args.unsupported = std::string{arg};
            return args;
        }
        args.files.emplace_back(argv[i]);
    }
    return args;
}

void print_hash_usage() {
    std::cerr << "Usage: branchaudit hash [--] <file>\n";
}

void print_root_usage() {
    std::cerr << "Usage: branchaudit root [--] [<file>...]\n";
}

void print_prove_usage() {
    std::cerr << "Usage: branchaudit prove <index> [--] <file>...\n";
}

void print_usage() {
    std::cerr << "Usage: branchaudit --version\n"
                 "       branchaudit hash [--] <file>\n"
                 "       branchaudit root [--] [<file>...]\n"
                 "       branchaudit prove <index> [--] <file>...\n";
}

// 解析 prove 的位置参数：只接受十进制数字（至少一位），且必须落在
// 可表示范围内；空串、含任何非数字字符或数值溢出都判为无效。
bool parse_index(const char* text, std::uint64_t& out) {
    const std::string_view sv{text};
    if (sv.empty()) {
        return false;
    }
    for (const char c : sv) {
        if (c < '0' || c > '9') {
            return false;
        }
    }
    const auto res =
        std::from_chars(sv.data(), sv.data() + sv.size(), out);
    return res.ec == std::errc{} && res.ptr == sv.data() + sv.size();
}

}  // namespace

int main(int argc, char* argv[]) {
    if (argc == 2 && std::string_view(argv[1]) == "--version") {
        std::cout << "branchaudit 0.1.0\n";
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "hash") {
        const FileArgs args = parse_file_args(argv, 2, argc);
        if (!args.unsupported.empty()) {
            std::cerr << "branchaudit hash: unsupported option '"
                      << args.unsupported << "'\n";
            print_hash_usage();
            return 2;
        }
        // 扣除结束标记后，hash 恰好接受一个文件；缺失或多给都属于用法错误。
        if (args.files.size() != 1) {
            std::cerr << "branchaudit hash: expected exactly one file, got "
                      << args.files.size() << '\n';
            print_hash_usage();
            return 2;
        }
        const branchaudit::FileHashResult result =
            branchaudit::sha256_file(args.files.front());
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        std::cout << branchaudit::to_hex(result.digest) << '\n';
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "root") {
        const FileArgs args = parse_file_args(argv, 2, argc);
        if (!args.unsupported.empty()) {
            std::cerr << "branchaudit root: unsupported option '"
                      << args.unsupported << "'\n";
            print_root_usage();
            return 2;
        }
        // root 接受零个或多个文件，顺序即命令行参数顺序：不排序、不去重。
        // 仅给结束标记时 files 为空，返回空批次根。
        const branchaudit::FileHashResult result =
            branchaudit::merkle_root_files(args.files);
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        std::cout << branchaudit::to_hex(result.digest) << '\n';
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "prove") {
        // 位置是第一个参数：缺失、含非数字或超出可表示范围都是用法错误。
        if (argc < 3) {
            std::cerr << "branchaudit prove: missing leaf index\n";
            print_prove_usage();
            return 2;
        }
        std::uint64_t index = 0;
        if (!parse_index(argv[2], index)) {
            std::cerr << "branchaudit prove: invalid leaf index '" << argv[2]
                      << "' (expected a decimal number)\n";
            print_prove_usage();
            return 2;
        }
        // 文件参数与 root 共用同一套定位与 "--" 规则：不排序、不去重。
        const FileArgs args = parse_file_args(argv, 3, argc);
        if (!args.unsupported.empty()) {
            std::cerr << "branchaudit prove: unsupported option '"
                      << args.unsupported << "'\n";
            print_prove_usage();
            return 2;
        }
        // 位置必须落在批次内；空批次没有合法位置。
        if (index >= args.files.size()) {
            std::cerr << "branchaudit prove: leaf index " << index
                      << " out of range for batch of " << args.files.size()
                      << " file(s)\n";
            print_prove_usage();
            return 2;
        }
        const branchaudit::MerkleProofResult result =
            branchaudit::merkle_proof_file(args.files, index);
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        // 单个 JSON 对象加换行；摘要均为 64 个小写十六进制字符。
        const branchaudit::MerkleProof& proof = result.proof;
        std::cout << "{\"version\":1"
                  << ",\"root\":\"" << branchaudit::to_hex(proof.root) << "\""
                  << ",\"leaf_count\":" << proof.leaf_count
                  << ",\"leaf_index\":" << proof.leaf_index
                  << ",\"leaf\":\"" << branchaudit::to_hex(proof.leaf) << "\""
                  << ",\"siblings\":[";
        for (std::size_t i = 0; i < proof.siblings.size(); ++i) {
            if (i != 0) {
                std::cout << ',';
            }
            const branchaudit::MerkleSibling& s = proof.siblings[i];
            std::cout << "{\"side\":\""
                      << (s.side == branchaudit::MerkleSibling::Side::left
                              ? "left"
                              : "right")
                      << "\",\"digest\":\"" << branchaudit::to_hex(s.digest)
                      << "\"}";
        }
        std::cout << "]}\n";
        return 0;
    }

    print_usage();
    return 2;
}

#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <string>
#include <string_view>
#include <vector>

#include "filehash.h"
#include "sha256.h"

namespace branchaudit {

// 32 字节原始摘要。Merkle 各层组合一律使用原始字节，不使用十六进制文本。
using Digest = std::array<std::uint8_t, Sha256::kDigestSize>;

// 空批次根：SHA-256 对空字节序列。
// 注意它与“单个空文件”的叶子摘要不同（叶子带 0x00 前缀）。
Digest merkle_empty_root();

// 文件叶子：SHA-256(0x00 || data)。
// 0x00 是值为 0x00 的单个原始前缀字节，不是字符串；data 为文件全部原始字节。
// 供已知字节内容时直接组合使用；文件请用流式的 merkle_root_files。
Digest merkle_leaf(const unsigned char* data, std::size_t size);

// 父摘要：SHA-256(0x01 || left || right)。
// 0x01 是值为 0x01 的单个原始前缀字节，left/right 各为 32 个原始字节，
// 先左后右，顺序不可交换。
Digest merkle_parent(const Digest& left, const Digest& right);

// 计算一个有序文件批次的 Merkle 根。
//
// 位置顺序完全取自 paths 的下标：不按文件名或摘要排序，也不去重；
// 同一路径重复出现、多个文件内容相同，都各自保留独立位置。根只反映各位置
// 的文件内容，不包含任何路径文字。
//
// 配对规则：每层相邻节点先左后右两两配对；若该层节点数为奇数，最后一个
// 节点没有伙伴，其摘要原样提升到上一层，不复制、不补零，直到只剩一个根。
// 只有一个文件时根即其叶子摘要；paths 为空时返回 merkle_empty_root()。
//
// 叶子按流式计算（固定缓冲），内存占用与文件大小无关。任一文件不存在、
// 指向目录、无法打开或读取失败时，整次计算失败：返回 error 非空的结果，
// 说明失败的路径和原因，不用其余文件产出部分结果。不打印、不退出进程。
FileHashResult merkle_root_files(const std::vector<std::filesystem::path>& paths);

// 证明路径上的一个兄弟节点：side 指明兄弟位于当前节点的哪一侧，
// digest 是该兄弟的摘要（32 个原始字节）。
struct MerkleSibling {
    enum class Side { left, right };
    Side side;
    Digest digest;
};

// 单个文件位置的成员证明。root 与 merkle_root_files 对同一有序批次的
// 结果一致；leaf 是被选文件带 0x00 前缀的叶子摘要；siblings 从叶子向根
// 逐层排列，只记录实际存在的兄弟——奇数末节点原样提升的层不添加记录，
// 不复制末节点、不补零。证明不含文件内容与路径。
struct MerkleProof {
    Digest root{};
    std::uint64_t leaf_count = 0;
    std::uint64_t leaf_index = 0;
    Digest leaf{};
    std::vector<MerkleSibling> siblings;
};

// merkle_proof_file 的结果：成功时 error 为空、proof 有效；
// 失败时 error 说明原因。
struct MerkleProofResult {
    MerkleProof proof;
    std::string error;

    bool ok() const { return error.empty(); }
};

// merkle_proof_parse_result（merkle_proof_from_json 的返回类型）与
// MerkleProofResult 一样只承载结构化结果，打印/退出策略由调用方决定。
struct MerkleProofParseResult {
    MerkleProof proof;
    std::string error;  // 失败时非空，是可直接展示给调用方用户的原因

    bool ok() const { return error.empty(); }
};

// merkle_verify_proof 的结果：通过时 valid 为真、error 为空；
// 任一条件不满足时 valid 为假，error 给出可供调用方直接展示的原因。
// 校验全程只返回结构化结果，不打印、不结束进程。
struct MerkleVerifyResult {
    bool valid = false;
    std::string error;

    bool ok() const { return valid && error.empty(); }
};

// 为有序批次中位于 leaf_index（从 0 开始）的文件生成成员证明。
//
// 批次规则与 merkle_root_files 完全相同：位置顺序取自 paths 下标，
// 不排序、不去重，同一路径重复出现各占一个位置；叶子按流式计算，
// 内存占用与文件大小无关。
//
// leaf_index 不落在批次内（paths 为空时没有任何合法位置）时返回 error
// 非空的结果；任一文件不存在、指向目录、无法打开或读取失败时整次失败，
// 返回 error 说明失败的路径和原因，不产出部分证明。不打印、不退出进程。
MerkleProofResult merkle_proof_file(
    const std::vector<std::filesystem::path>& paths, std::uint64_t leaf_index);

// 校验一份成员证明，判断“某份内容是否受到可信根支持”，并核对证明的
// 兄弟记录是否与证明自报的 leaf_count/leaf_index 一致。
//
// 只消费三项已有输入，不读取文件、不重新提供或扫描整个批次：
//  * proof：merkle_proof_file 产出的证明结构；
//  * trusted_root：调用方另行持有的可信批次根摘要（32 个原始字节，例如
//    来自独立渠道保存的 root 输出），不能用 proof.root 充当信任依据；
//  * content_leaf：待验证内容按现有叶子规则计算的摘要
//    SHA-256(0x00 || content)（32 个原始字节），即 merkle_leaf 对该内容
//    的输出；它带单个 0x00 前缀，不能用 hash/sha256_file 输出的普通文件
//    摘要替代。
//
// 仅当以下条件同时成立才通过：
//  1. content_leaf 与 proof.leaf 完全一致；
//  2. proof.root 与 trusted_root 完全一致（信任锚只来自调用方传入）；
//  3. proof.siblings 能按 0x01 父节点字节规则从 content_leaf 折叠回
//     trusted_root；
//  4. siblings 的方向、数量与从叶子向根的次序严格符合 proof.leaf_count 与
//     proof.leaf_index 所描述的位置：leaf_count 为零（空批次）没有成员；
//     leaf_index 必须小于 leaf_count；每项 side 只能是 left 或 right；
//     奇数层末节点原样提升的层本就没有兄弟，生成端省略这些层记录的证明
//     正常通过，不要求补齐；缺少必要项或多出项都判失败。因此一份内部
//     自洽但属于另一批次（另一可信根）或位置结构不符的证明不会通过。
//
// 通过的含义需要准确理解：它表明该内容受到可信根支持，且兄弟记录与证明
// 自报的 leaf_count/leaf_index 一致；但这两个数字是证明自带的声明，
// 校验无法证明它们就是原始批次的真实大小与位置——同一份根、叶子与兄弟
// 记录可能同时与多组 (leaf_count, leaf_index) 自洽（例如三条目批次
// 位置 2 的证明，把声明改成 leaf_count=2、leaf_index=1 后依然通过，
// 因为该位置首层是奇数末节点、无兄弟记录，路径形状与后者完全相同）。
// 业务若要求“内容属于条目数已知的批次且处于指定位置”，调用方必须把
// proof.leaf_count/leaf_index 与随可信根一起独立保存的批次大小和预期
// 位置逐一比对，不一致时拒绝位置认定，不能以本函数的通过代替这一比对。
// 当然，并非任意改写声明数字都能通过：leaf_index 越界、或声明的位置与
// 兄弟记录的方向/数量/次序不符，仍会被拒绝。
//
// leaf_count/leaf_index 沿用无符号 64 位范围；结构推导只做不回绕的整数
// 运算且层数有界，最大可表示的合法计数（UINT64_MAX）也有确定结果，不会
// 因数值回绕误判或无法结束。单文件批次只接受位置 0 与空兄弟列表；空文件
// 的叶子（SHA-256(0x00)）与空批次根不同，不会互相冒充；重复内容各占独立
// 位置，校验按位置结构核对，不按摘要去重。
//
// 成功时返回 {valid=true, error=""}；失败时 valid 为假，error 为可供调用
// 方直接展示的原因。函数只返回结构化结果，不打印、不退出进程。
MerkleVerifyResult merkle_verify_proof(const MerkleProof& proof,
                                       const Digest& trusted_root,
                                       const Digest& content_leaf);

// 从 prove 命令输出的版本 1 JSON 文本读取成员证明。
//
// 只消费调用方传入的 text：不读取任何批次文件，不访问文件系统，也不替
// 调用方选择可信根——证明自报的 root 只是被校验的声明，可信根必须由调用
// 方经独立渠道另行保存并在随后交给 merkle_verify_proof。
//
// 接受 prove 已公开的版本 1 字段与兄弟记录格式，字段为：
//  * version：只接受 JSON 整数 1（小数、字符串、布尔等一律拒绝）；
//  * root / leaf：只接受恰好 64 个小写十六进制字符的 JSON 字符串，还原
//    为 32 个原始字节；长度不符、含非十六进制字符或使用大写字符都明确
//    失败，不截断、不替换损坏内容；
//  * leaf_count / leaf_index：只接受 0..2^64-1 的 JSON 整数，数值必须
//    准确保留；负数、小数、指数写法、数字字符串、布尔值以及超出无符号
//    64 位范围的数字都拒绝；
//  * siblings：JSON 数组，顺序、方向与摘要严格按输入保留——不重新排序、
//    不去重，也不为奇数末节点原样提升的层补记录；单文件证明的空数组
//    正常读入。每项是只含 side 与 digest 的对象，side 只接受字符串
//    "left" / "right"，digest 遵守与上面相同的 64 位小写十六进制规则；
//    每项的字段集合同样不允许重复或多余字段。
//
// 完整接受命令输出，包括末尾换行；合法的 JSON 空白（空格、制表符、回车、
// 换行）出现在任何记号之间都不影响读取，对象字段次序任意。顶层必须恰好
// 是一个 JSON 对象：文本为空、JSON 语法损坏、必填字段缺失、字段类型不符、
// 同一对象出现重复字段、出现未定义字段、版本不支持，或对象之后除 JSON
// 空白外还有任何内容，都判为读取失败——不会只取前半段当作成功。
//
// 读取成功只表示 text 符合证明格式，绝不等于成员校验通过：空批次、位置
// 越界、兄弟路径与计数/位置不匹配、摘要能否折叠到可信根等全部继续由
// merkle_verify_proof 判断；证明自报的 root、leaf_count、leaf_index
// 仍是未经认证的声明。
//
// 失败时 error 为可供直接展示的原因，返回的 proof 不提供可用的部分证明
// （保持默认构造状态）。函数全程只返回结构化结果，不向标准输出/错误
// 打印，也不结束调用方进程。
MerkleProofParseResult merkle_proof_from_json(std::string_view text);

