81	// ---- prove 版本 1 JSON 的严格读取 -----------------------------------------
82	//
83	// 只实现 prove 已公开的格式所需的 JSON 子集：对象、数组、字符串、整数。
84	// 不接受小数、指数、null/true/false 作为字段值；空白与字段次序按 JSON
85	// 规则自由；重复字段、未知字段与对象之后的多余内容一律判错。解析器只
86	// 扫描传入文本，不做任何文件或内存映射 I/O。
87	
88	struct JsonParser {
89	    std::string_view text;
90	    std::size_t pos = 0;
91	    std::string error;
92	
93	    void ws() {
94	        while (pos < text.size()) {
95	            const char c = text[pos];
96	            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
97	                ++pos;
98	            } else {
99	                break;
100	            }
101	        }
102	    }
103	
104	    bool eof() const { return pos >= text.size(); }
105	
106	    char peek() const { return text[pos]; }
107	
108	    bool fail(std::string msg) {
109	        // 每个调用点只会在尚未出错时进入；保留第一条原因。
110	        if (error.empty()) {
111	            error = std::move(msg);
112	        }
113	        return false;
114	    }
115	
116	    // 读取一个 JSON 字符串字面量（text[pos] 必须是 '"'），把解码后的
117	    // UTF-8 内容写入 out。prove 的摘要/字段名/side 都只含 ASCII，这里仍
118	    // 按 JSON 规则处理转义与 uXXXX（含代理对），以便对任意输入给出确定
119	    // 结果而非越界读取。
120	    bool read_string(std::string& out) {
121	        out.clear();
122	        ++pos;  // 跳过起始引号
123	        while (true) {
124	            if (eof()) {
125	                return fail("unterminated JSON string");
126	            }
127	            const char c = text[pos++];
128	            if (static_cast<unsigned char>(c) < 0x20) {
129	                return fail("unescaped control character in JSON string");
130	            }
131	            if (c == '"') {
132	                return true;
133	            }
134	            if (c == '\\') {
135	                if (eof()) {
136	                    return fail("unterminated escape in JSON string");
137	                }
138	                const char e = text[pos++];
139	                switch (e) {
140	                    case '"': out.push_back('"'); break;
141	                    case '\\': out.push_back('\\'); break;
142	                    case '/': out.push_back('/'); break;
143	                    case 'b': out.push_back('\b'); break;
144	                    case 'f': out.push_back('\f'); break;
145	                    case 'n': out.push_back('\n'); break;
146	                    case 'r': out.push_back('\r'); break;
147	                    case 't': out.push_back('\t'); break;
148	                    case 'u': {
149	                        std::uint32_t cp = 0;
150	                        if (!read_hex4(cp)) {
151	                            return fail("invalid \\u escape in JSON string");
152	                        }
153	                        // UTF-16 代理对：\uD800-\uDBFF 后必须紧跟
154	                        // \uDC00-\uDFFF。
155	                        if (cp >= 0xD800 && cp <= 0xDBFF) {
156	                            if (pos + 1 < text.size() && text[pos] == '\\' &&
157	                                text[pos + 1] == 'u') {
158	                                pos += 2;
159	                                std::uint32_t lo = 0;
160	                                if (!read_hex4(lo) || lo < 0xDC00 ||
161	                                    lo > 0xDFFF) {
162	                                    return fail("invalid UTF-16 surrogate pair "
163	                                                "in JSON string");
164	                                }
165	                                cp = 0x10000 + ((cp - 0xD800) << 10) +
166	                                     (lo - 0xDC00);
167	                            } else {
168	                                return fail("lone UTF-16 high surrogate in JSON "
169	                                            "string");
170	                            }
171	                        } else if (cp >= 0xDC00 && cp <= 0xDFFF) {
172	                            return fail("lone UTF-16 low surrogate in JSON "
173	                                        "string");
174	                        }
175	                        append_utf8(cp, out);
176	                        break;
177	                    }
178	                    default:
179	                        return fail("invalid escape sequence in JSON string");
180	                }
181	            } else {
182	                out.push_back(c);
183	            }
184	        }
185	    }
186	
187	    // 从 text[pos..pos+4) 读取四个十六进制位；不足或非法返回 false。
188	    bool read_hex4(std::uint32_t& out) {
189	        if (pos + 4 > text.size()) {
190	            return false;
191	        }
192	        std::uint32_t v = 0;
193	        for (int i = 0; i < 4; ++i) {
194	            const char c = text[pos++];
195	            v <<= 4;
196	            if (c >= '0' && c <= '9') {
197	                v |= static_cast<std::uint32_t>(c - '0');
198	            } else if (c >= 'a' && c <= 'f') {
199	                v |= static_cast<std::uint32_t>(c - 'a' + 10);
200	            } else if (c >= 'A' && c <= 'F') {
201	                v |= static_cast<std::uint32_t>(c - 'A' + 10);
202	            } else {
203	                return false;
204	            }
205	        }
206	        out = v;
207	        return true;
208	    }
209	
210	    static void append_utf8(std::uint32_t cp, std::string& out) {
211	        if (cp <= 0x7F) {
212	            out.push_back(static_cast<char>(cp));
213	        } else if (cp <= 0x7FF) {
214	            out.push_back(static_cast<char>(0xC0 | (cp >> 6)));
215	            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
216	        } else if (cp <= 0xFFFF) {
217	            out.push_back(static_cast<char>(0xE0 | (cp >> 12)));
218	            out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
219	            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
220	        } else {
221	            out.push_back(static_cast<char>(0xF0 | (cp >> 18)));
222	            out.push_back(static_cast<char>(0x80 | ((cp >> 12) & 0x3F)));
223	            out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
224	            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
225	        }
226	    }
