386	// ---- 对象字段的表驱动通用读取 ----------------------------------------------
387	//
388	// 证明对象与兄弟对象共用同一套字段循环：字段名、冒号、值、逗号/闭括号分隔、
389	// 未知字段、重复字段与必填字段检查只在此实现一次；两种对象的差别（允许哪
390	// 些字段、值如何读取、错误文字）全部由 JsonObjectSpec 表描述，同类规则不
391	// 再需要两处维护。
392	
393	// 一个对象字段：name 是解码后的字段名；bit 用于已见/必填掩码；read_value
394	// 在 ':' 之后读取该字段的值并写入 target（证明对象时为 MerkleProof*，
395	// 兄弟对象时为 MerkleSibling*）。
396	struct JsonFieldSpec {
397	    std::string_view name;
398	    unsigned bit;
399	    bool (*read_value)(JsonParser& p, void* target);
400	};
401	
402	// 一种 JSON 对象的读取规则与错误文字。
403	struct JsonObjectSpec {
404	    const JsonFieldSpec* fields;
405	    std::size_t field_count;
406	    unsigned all_bits;              // 全部必填字段的位掩码
407	    std::string_view expect_key_msg;      // 字段名位置不是字符串
408	    std::string_view key_noun;            // “expected ':' after …”中的称谓
409	    std::string_view undefined_suffix;    // 未知字段错误中 "in …" 部分
410	    std::string_view duplicate_suffix;    // 重复字段错误中 "in …" 部分
411	    std::string_view unterminated_msg;    // 值之后输入即结束
412	    std::string_view separator_msg;       // 值之后既不是 ',' 也不是 '}'
413	    std::string_view empty_object_msg;    // 非空："{}" 立即报此错；
414	                                          // 空：留给必填字段检查
415	    std::string_view missing_fixed_msg;   // 非空：缺必填字段报此固定原因
416	    std::string_view missing_list_prefix; // 否则：此前缀 + 缺失字段名列表
417	};
418	
419	// 通用对象字段循环：调用时 p 已停在起始 '{' 之后的位置。逐字段读取
420	// "key": value 并处理 ','/'}' 分隔；未知字段、重复字段、损坏的分隔符都
421	// 在此拒绝。成功返回时 seen 记录已出现字段的位掩码（必填字段是否齐全由
422	// 调用方用 check_required_fields 判断）。
423	bool read_object_fields(JsonParser& p, const JsonObjectSpec& spec,
424	                        void* target, unsigned& seen) {
425	    seen = 0;
426	    p.ws();
427	    if (!p.eof() && p.peek() == '}') {
428	        ++p.pos;
429	        if (!spec.empty_object_msg.empty()) {
430	            return p.fail(std::string(spec.empty_object_msg));
431	        }
432	        return true;  // 空对象：缺失字段由必填检查报告。
433	    }
434	    while (true) {
435	        p.ws();
436	        if (p.eof() || p.peek() != '"') {
437	            return p.fail(std::string(spec.expect_key_msg));
438	        }
439	        std::string key;
440	        if (!p.read_string(key)) {
441	            return false;
442	        }
443	        p.ws();
444	        if (p.eof() || p.peek() != ':') {
445	            return p.fail("expected ':' after " + std::string(spec.key_noun) +
446	                          " \"" + key + "\"");
447	        }
448	        ++p.pos;
449	
450	        const JsonFieldSpec* field = nullptr;
451	        for (std::size_t i = 0; i < spec.field_count; ++i) {
452	            if (spec.fields[i].name == key) {
453	                field = &spec.fields[i];
454	                break;
455	            }
456	        }
457	        if (field == nullptr) {
458	            return p.fail("undefined field \"" + key + "\" " +
459	                          std::string(spec.undefined_suffix));
460	        }
461	        if (seen & field->bit) {
462	            return p.fail("duplicate field \"" + key + "\" " +
463	                          std::string(spec.duplicate_suffix));
464	        }
465	        if (!field->read_value(p, target)) {
466	            return false;
467	        }
468	        seen |= field->bit;
469	
470	        p.ws();
471	        if (p.eof()) {
472	            return p.fail(std::string(spec.unterminated_msg));
473	        }
474	        if (p.peek() == '}') {
475	            ++p.pos;
476	            return true;
477	        }
478	        if (p.peek() != ',') {
479	            return p.fail(std::string(spec.separator_msg));
480	        }
481	        ++p.pos;
482	        // 逗号之后要求另一个字段名；循环回到顶部做该检查。
483	    }
484	}
485	
486	// 必填字段检查：spec.missing_fixed_msg 非空时给出该固定原因，否则按字段
487	// 表顺序列出缺失字段名。字段齐全时不产生错误。
488	bool check_required_fields(JsonParser& p, const JsonObjectSpec& spec,
489	                           unsigned seen) {
490	    if (seen == spec.all_bits) {
491	        return true;
492	    }
493	    if (!spec.missing_fixed_msg.empty()) {
494	        return p.fail(std::string(spec.missing_fixed_msg));
495	    }
496	    std::string missing;
497	    for (std::size_t i = 0; i < spec.field_count; ++i) {
498	        if (!(seen & spec.fields[i].bit)) {
499	            if (!missing.empty()) {
500	                missing += ", ";
501	            }
502	            missing += '"';
503	            missing += spec.fields[i].name;
504	            missing += '"';
505	        }
506	    }
507	    return p.fail(std::string(spec.missing_list_prefix) + missing);
508	}
