545	bool parse_siblings_array(JsonParser& p,
546	                          std::vector<MerkleSibling>& siblings);
547	
548	bool read_proof_siblings(JsonParser& p, void* target) {
549	    p.ws();
550	    if (p.eof() || p.peek() != '[') {
