557	enum ProofFieldBit : unsigned {
558	    kVersion = 1u << 0,
559	    kRoot = 1u << 1,
560	    kLeafCount = 1u << 2,
561	    kLeafIndex = 1u << 3,
562	    kLeaf = 1u << 4,
563	    kSiblings = 1u << 5,
564	};
565	
566	// 字段表顺序即必填缺失清单的列出顺序。
567	const JsonFieldSpec kProofFields[] = {
568	    {"version", kVersion, &read_proof_version},
569	    {"root", kRoot, &read_proof_root},
570	    {"leaf_count", kLeafCount, &read_proof_leaf_count},
571	    {"leaf_index", kLeafIndex, &read_proof_leaf_index},
572	    {"leaf", kLeaf, &read_proof_leaf},
573	    {"siblings", kSiblings, &read_proof_siblings},
574	};
575	
576	const JsonObjectSpec kProofObjectSpec = {
577	    kProofFields,
578	    sizeof(kProofFields) / sizeof(kProofFields[0]),
579	    kVersion | kRoot | kLeafCount | kLeafIndex | kLeaf | kSiblings,
580	    "expected a string field name in proof object",
581	    "proof object field",
582	    "in proof object (version 1 defines only version, root, leaf_count, "
583	    "leaf_index, leaf and siblings)",
584	    "in proof object",
585	    "unterminated proof object",
586	    "expected ',' or '}' in proof object",
587	    "",  // 空证明对象不立即报错：由必填检查列出全部缺失字段。
588	    "",
589	    "proof object is missing required field(s): ",
590	};
591	
592	// ---- 兄弟对象的字段 ----------------------------------------------------------
593	
594	bool read_sibling_side(JsonParser& p, void* target) {
595	    MerkleSibling& sibling = *static_cast<MerkleSibling*>(target);
596	    std::string side;
597	    if (!p.read_string_value(side, "side")) {
598	        return false;
599	    }
600	    if (side == "left") {
601	        sibling.side = MerkleSibling::Side::left;
602	    } else if (side == "right") {
603	        sibling.side = MerkleSibling::Side::right;
604	    } else {
605	        return p.fail("sibling side must be \"left\" or \"right\"");
606	    }
607	    return true;
608	}
609	
610	bool read_sibling_digest(JsonParser& p, void* target) {
611	    return read_digest_value(p, static_cast<MerkleSibling*>(target)->digest,
612	                             "digest");
613	}
614	
615	enum SiblingFieldBit : unsigned {
616	    kSide = 1u << 0,
617	    kDigest = 1u << 1,
618	};
619	
620	const JsonFieldSpec kSiblingFields[] = {
621	    {"side", kSide, &read_sibling_side},
622	    {"digest", kDigest, &read_sibling_digest},
623	};
624	
625	const JsonObjectSpec kSiblingObjectSpec = {
626	    kSiblingFields,
627	    sizeof(kSiblingFields) / sizeof(kSiblingFields[0]),
628	    kSide | kDigest,
629	    "expected string key in sibling object",
630	    "sibling object key",
631	    "in a siblings entry (only \"side\" and \"digest\" are allowed)",
632	    "in a siblings entry",
633	    "unterminated sibling object",
634	    "expected ',' or '}' in sibling object",
635	    "a siblings entry must contain \"side\" and \"digest\"",
636	    "a siblings entry must contain both \"side\" and \"digest\"",
637	    "",
638	};
639	
640	// 解析一个兄弟对象：只允许 side 与 digest 两个字段，均必填、不得重复、
641	// 不得出现其他字段。调用时 p 已停在起始 '{' 之后的位置。
642	bool parse_sibling_object(JsonParser& p, MerkleSibling& sibling) {
643	    unsigned seen = 0;
644	    if (!read_object_fields(p, kSiblingObjectSpec, &sibling, seen)) {
645	        return false;
646	    }
647	    return check_required_fields(p, kSiblingObjectSpec, seen);
648	}
649	
650	// 解析 siblings 数组：顺序、方向与摘要严格按输入保留，不排序、不去重、
651	// 不补记录。调用时 p 已确认当前字符为 '['。
652	bool parse_siblings_array(JsonParser& p,
653	                          std::vector<MerkleSibling>& siblings) {
654	    ++p.pos;  // 跳过 '['
655	    p.ws();
656	    if (!p.eof() && p.peek() == ']') {
657	        ++p.pos;
658	        return true;  // 单文件证明的空兄弟数组。
659	    }
660	    while (true) {
661	        p.ws();
662	        if (p.eof()) {
663	            return p.fail("unterminated siblings array");
664	        }
665	        if (p.peek() != '{') {
666	            return p.fail("each siblings entry must be a JSON object");
667	        }
668	        ++p.pos;  // 跳过 '{'
669	        MerkleSibling& sibling = siblings.emplace_back();
670	        if (!parse_sibling_object(p, sibling)) {
671	            return false;
672	        }
673	        p.ws();
674	        if (p.eof()) {
675	            return p.fail("unterminated siblings array");
676	        }
677	        if (p.peek() == ']') {
678	            ++p.pos;
679	            return true;
680	        }
681	        if (p.peek() != ',') {
682	            return p.fail("expected ',' or ']' in siblings array");
683	        }
684	        ++p.pos;
685	    }
686	}
