690	FileHashResult merkle_root_files(const std::vector<std::filesystem::path>& paths) {
691	    FileHashResult result;
692	
693	    // 没有文件：空字节序列的 SHA-256。
694	    if (paths.empty()) {
695	        result.digest = merkle_empty_root();
696	        return result;
697	    }
698	
699	    // 叶子层。
700	    std::vector<Digest> level;
701	    result.error = leaf_level(paths, level);
702	    if (!result.ok()) {
703	        return result;
704	    }
705	
706	    // 逐层相邻配对直到只剩一个根；配对与奇数末节点原样提升的规则由
707	    // combine_level 唯一实现，prove 沿同一函数走，两条路径不会出现规则漂移。
708	    while (level.size() > 1) {
709	        level = combine_level(level);
710	    }
711	
712	    result.digest = level.front();
713	    return result;
714	}
715	
716	MerkleProofResult merkle_proof_file(
717	        const std::vector<std::filesystem::path>& paths,
718	        std::uint64_t leaf_index) {
719	    MerkleProofResult result;
720	
721	    // 位置必须落在批次内；空批次没有任何合法位置。
722	    if (leaf_index >= paths.size()) {
723	        result.error = "leaf index " + std::to_string(leaf_index) +
724	                       " out of range for batch of " +
725	                       std::to_string(paths.size()) + " file(s)";
726	        return result;
727	    }
728	
729	    // 叶子层：与 merkle_root_files 完全相同的文件与顺序规则。
730	    std::vector<Digest> level;
731	    result.error = leaf_level(paths, level);
732	    if (!result.ok()) {
733	        return result;
734	    }
735	
736	    MerkleProof& proof = result.proof;
737	    proof.leaf_count = paths.size();
738	    proof.leaf_index = leaf_index;
739	    proof.leaf = level[static_cast<std::size_t>(leaf_index)];
740	
741	    // 沿被选位置逐层向上：每层只记录实际存在的兄弟；奇数末节点原样
742	    // 提升的层没有兄弟，不添加记录（不复制末节点、不补零）。该层如何
743	    // 合并与 root 完全相同——两者都调用同一份 combine_level。
744	    std::size_t idx = static_cast<std::size_t>(leaf_index);
745	    while (level.size() > 1) {
746	        if (idx % 2 == 0) {
747	            if (idx + 1 < level.size()) {
748	                proof.siblings.push_back(
749	                    {MerkleSibling::Side::right, level[idx + 1]});
750	            }
751	            // idx 是奇数层的末节点：经 combine_level 原样提升，无兄弟记录。
752	        } else {
753	            proof.siblings.push_back(
754	                {MerkleSibling::Side::left, level[idx - 1]});
755	        }
756	
757	        idx /= 2;
758	        level = combine_level(level);
759	    }
760	
761	    proof.root = level.front();
762	    return result;
763	}
764	
765	MerkleVerifyResult merkle_verify_proof(const MerkleProof& proof,
766	                                       const Digest& trusted_root,
767	                                       const Digest& content_leaf) {
768	    MerkleVerifyResult result;
769	
770	    // 空批次没有任何成员；位置必须从 0 开始并落在批次内。
771	    if (proof.leaf_count == 0) {
772	        result.error =
773	            "proof rejected: empty batch (leaf_count is 0) has no members";
774	        return result;
775	    }
776	    if (proof.leaf_index >= proof.leaf_count) {
777	        result.error =
778	            "proof rejected: leaf_index " +
779	            std::to_string(proof.leaf_index) + " is out of range for leaf_count " +
780	            std::to_string(proof.leaf_count);
781	        return result;
782	    }
783	
784	    // 条件 1：待验证内容的叶子摘要必须与证明中的叶子完全一致。
785	    // content_leaf 按叶子规则带单个 0x00 前缀；普通文件摘要（无此前缀）
786	    // 不可能与真实叶子相等，不能借此通过。
787	    if (content_leaf != proof.leaf) {
788	        result.error =
789	            "proof rejected: supplied content leaf digest does not match the "
790	            "leaf digest in the proof";
791	        return result;
792	    }
793	
794	    // 条件 4 + 条件 3 的折叠：兄弟的方向、数量与从叶子向根的次序必须严格
795	    // 符合 (leaf_count, leaf_index) 描述的位置；在逐层核对的同时按
796	    // SHA-256(0x01||left||right) 折叠。不能只在最后比对摘要——结构不符
797	    // （侧向错、缺项、多项、次序错）即使凑出相等摘要也必须拒绝。
798	    //
799	    // 各层节点数只做纯 uint64 模拟，绝不按 leaf_count 分配内存；上一层
800	    // 大小为 ceil(n/2)，写成 n - n/2 —— n 为奇数时 (n+1)/2 在
801	    // n=UINT64_MAX 处会回绕，n - n/2 不会。层数关于 n 有界（至多 64 层），
802	    // 因此最大可表示的合法计数也立即得到确定结果。
803	    std::uint64_t level_size = proof.leaf_count;
804	    std::uint64_t pos = proof.leaf_index;
805	    std::uint64_t tree_level = 0;  // 叶子之上第一层为 0，仅用于错误信息
806	    std::size_t consumed = 0;
807	    Digest node = content_leaf;
808	
809	    while (level_size > 1) {
810	        // 与 merkle_proof_file 的记录规则完全一致：偶数位置且该位置是
811	        // 奇数层末节点时，节点原样提升，本层没有兄弟、不消费记录；
812	        // 偶数且右侧仍有伙伴 -> 必须有 right 兄弟；奇数位置 -> 必须有
813	        // left 兄弟（pos>=1，左侧伙伴必然存在）。
814	        // 写成 pos == level_size - 1 而非 pos + 1 >= level_size：
815	        // level_size > 1 保证减法安全，而 pos+1 在 pos=UINT64_MAX 时会
816	        // 无符号回绕成 0，恰好把“末节点提升”误判成“右侧有兄弟”。
817	        const bool promoted_without_sibling =
818	            (pos % 2 == 0) && (pos == level_size - 1);
819	
820	        if (!promoted_without_sibling) {
821	            if (consumed >= proof.siblings.size()) {
822	                result.error =
823	                    "proof rejected: missing required sibling at tree level " +
824	                    std::to_string(tree_level) + " for leaf_index " +
825	                    std::to_string(proof.leaf_index) + " of leaf_count " +
826	                    std::to_string(proof.leaf_count);
827	                return result;
828	            }
829	
830	            const MerkleSibling& sibling = proof.siblings[consumed];
831	
832	            // side 只能是 left 或 right：证明结构可能由调用方自行构造，
833	            // 非法枚举值也必须明确拒绝，不能落入任一分支碰运气。
834	            bool sibling_on_right;
835	            if (sibling.side == MerkleSibling::Side::right) {
836	                sibling_on_right = true;
837	            } else if (sibling.side == MerkleSibling::Side::left) {
838	                sibling_on_right = false;
839	            } else {
840	                result.error =
841	                    "proof rejected: sibling at tree level " +
842	                    std::to_string(tree_level) +
843	                    " has an invalid side (only left or right is allowed)";
844	                return result;
845	            }
846	
847	            const bool expected_on_right = (pos % 2 == 0);
848	            if (sibling_on_right != expected_on_right) {
849	                result.error =
850	                    "proof rejected: sibling at tree level " +
851	                    std::to_string(tree_level) + " is on the " +
852	                    (sibling_on_right ? "right" : "left") +
853	                    " side, but the position in the batch requires it on the " +
854	                    (expected_on_right ? "right" : "left");
855	                return result;
856	            }
857	
858	            node = sibling_on_right
859	                       ? merkle_parent(node, sibling.digest)
860	                       : merkle_parent(sibling.digest, node);
861	            ++consumed;
862	        }
863	        // 原样提升或正常配对后，被选位置在上一层的下标都是 floor(pos/2)；
864	        // pos 始终小于 level_size，不会触及 UINT64_MAX 回绕。
865	        pos /= 2;
866	        ++tree_level;
867	        const std::uint64_t half = level_size / 2;
868	        level_size -= half;  // ceil(level_size/2)，无回绕。
869	    }
870	
871	    // 到达根后不得还有多余兄弟。
872	    if (consumed != proof.siblings.size()) {
873	        result.error =
874	            "proof rejected: proof carries " +
875	            std::to_string(proof.siblings.size()) +
876	            " sibling(s), but the batch position requires exactly " +
877	            std::to_string(consumed);
878	        return result;
879	    }
880	
881	    // 条件 2：信任锚只来自调用方单独传入的可信根；证明自报的 root 不能
882	    // 充当信任依据——属于另一批次的证明即使内部自洽也在此被拒。
883	    if (proof.root != trusted_root) {
884	        result.error =
885	            "proof rejected: root claimed by the proof does not match the "
886	            "trusted batch root";
887	        return result;
888	    }
889	
890	    // 条件 3：兄弟必须真的把内容叶子折叠到可信根（防止 root 字段被改成
891	    // 可信根、但兄弟链与叶子并不相容的证明）。
892	    if (node != trusted_root) {
893	        result.error =
894	            "proof rejected: the supplied siblings do not combine the content "
895	            "leaf into the trusted batch root";
896	        return result;
897	    }
898	
899	    result.valid = true;
900	    return result;
901	}
902	
903	MerkleProofParseResult merkle_proof_from_json(std::string_view text) {
904	    MerkleProofParseResult result;
905	
906	    // 全程写入本地 proof：只有文本完整通过后才移入返回值，任何失败都不
907	    // 留下可用的部分证明（返回对象保持默认构造）。
908	    MerkleProof proof;
909	    JsonParser p;
910	    p.text = text;
911	
912	    p.ws();
913	    if (p.eof()) {
914	        result.error =
915	            "proof text rejected: input is empty or whitespace only "
916	            "(expected a version 1 proof JSON object)";
917	        return result;
918	    }
919	    if (p.peek() != '{') {
920	        result.error =
921	            "proof text rejected: top-level value must be a single JSON object";
922	        return result;
923	    }
924	    ++p.pos;
925	
926	    // 字段循环、分隔符、未知/重复字段检查与兄弟对象共用同一份实现；
927	    // 版本 1 的字段集合与值约束由 kProofObjectSpec 唯一描述。
928	    unsigned seen = 0;
929	    if (p.error.empty()) {
930	        read_object_fields(p, kProofObjectSpec, &proof, seen);
931	    }
932	
933	    if (p.error.empty()) {
934	        // 对象之后除 JSON 空白外不得再有任何内容：不能只取前半段当作成功。
935	        p.ws();
936	        if (!p.eof()) {
937	            p.fail("unexpected trailing content after the proof JSON object");
938	        }
939	    }
940	    if (p.error.empty()) {
941	        check_required_fields(p, kProofObjectSpec, seen);
942	    }
943	
944	    if (!p.error.empty()) {
945	        result.error = "proof text rejected: " + p.error;
946	        return result;
947	    }
948	
949	    result.proof = std::move(proof);
950	    return result;
951	}
952	
953	}  // namespace branchaudit
