                  "single-file proof: empty siblings, root equals leaf");
            check(merkle_verify_proof(r.proof, lempty, lempty).ok(),
                  "single-file parsed proof verifies");
        }
    }

    // 两文件、左右各一：兄弟方向按输入保留。
    {
