    if (!lib || getenv("BRANCHAUDIT_FAULT_REEXECED")) return;

    std::string preload = lib;
    if (const char *existing = std::getenv("LD_PRELOAD")) {
        if (*existing) {
            preload.push_back(':');
            preload += existing;
        }
    }
    setenv("LD_PRELOAD", preload.c_str(), 1);
    setenv("BRANCHAUDIT_FAULT_REEXECED", "1", 1);

